def targetDate = nowTimestamp.toLocalDateTime().minusDays(interval * intervalDays)
def packedDateStart = Timestamp.valueOf(targetDate.truncatedTo(ChronoUnit.DAYS))
def packedDateEnd = Timestamp.valueOf(targetDate.truncatedTo(ChronoUnit.DAYS).plusDays(1).minus(1, ChronoUnit.MILLIS))
